#!/usr/bin/env python3
"""Append an auditable mechanism view without changing historical explorer sections."""
import argparse,base64,copy,hashlib,json,pathlib,re,shutil
ROOT=pathlib.Path(__file__).resolve().parents[1];BASE=ROOT/'docs/mechanism';START='<!-- TAILCACHE_MECHANISM_START -->';END='<!-- TAILCACHE_MECHANISM_END -->'
def strip(s):return re.sub(re.escape(START)+'.*?'+re.escape(END),'',s,flags=re.S)
def render(hosted=False):
 path=BASE/'mechanism-data-20261118.json';d=json.loads(path.read_text());summary=copy.deepcopy(d)
 for r in summary['forks']:
  for k in ('distributions','measuredPauses','safepoints','windows','rawSha256'):r.pop(k,None)
 for c in summary['cohorts'].values():
  c.pop('protocol',None);c['audit']={'passed':c['audit']['passed']}
 summary.pop('controls',None);raw=json.dumps(summary,separators=(',',':'));full=path.read_text();assert '</script' not in (raw+full).lower()
 css='''<style>#mechanism-followup{margin:26px 0;padding:clamp(16px,3vw,36px);background:#f5f8fb;color:#162b3c;border:1px solid #bfd0df;border-radius:18px}#mechanism-followup img{max-width:100%;height:auto}#mechanism-followup figure{margin:22px 0}#mechanism-followup figcaption{line-height:1.6}#mechanism-followup h2{font-size:clamp(25px,4vw,38px);line-height:1.14;margin:8px 0 18px}#mechanism-followup p{line-height:1.65}#mechanism-followup label{display:inline-flex;flex-direction:column;gap:6px;margin:10px 12px 10px 0;font-weight:650}#mechanism-followup select{max-width:100%;font:inherit;padding:10px;border:1px solid #93aabb;border-radius:6px;background:white;color:#162b3c}#mechanism-followup button,#mechanism-followup .mf-link{display:inline-block;padding:11px 16px;border:1px solid #246387;border-radius:6px;background:#246387;color:white;font:inherit;text-decoration:none}#mechanism-followup .mf-scroll{overflow:auto;max-width:100%;margin:16px 0}#mechanism-followup table{border-collapse:collapse;width:100%;font-size:13px}#mechanism-followup th,#mechanism-followup td{text-align:left;border-bottom:1px solid #ccd9e2;padding:10px;vertical-align:top}#mechanism-followup th{background:#e5edf4}#mechanism-followup td:first-child{min-width:210px}#mechanism-followup dl{display:grid;grid-template-columns:minmax(130px,1fr) 3fr;gap:14px}#mechanism-followup dd{margin:0;line-height:1.6}#mechanism-followup .mf-note{padding:15px;background:#fff3db;border-left:4px solid #a06a16}#mechanism-followup details{margin:18px 0}#mechanism-followup summary{cursor:pointer;font-weight:700;padding:8px}@media(max-width:600px){#mechanism-followup dl{display:block}#mechanism-followup dt{margin-top:18px}#mechanism-followup label{display:flex;margin-right:0}#mechanism-followup{border-radius:10px}}</style>'''
 body='''<section id="mechanism-followup" aria-labelledby="mf-title" data-package-url="mechanism-data.json" data-package-sha="'''+hashlib.sha256(path.read_bytes()).hexdigest()+'''"><p>Mechanism experiments · 18 November 2026</p><h2 id="mf-title">What moves the response tail?</h2><p>Separate paired interventions test logging, phase priming, update locality, longer transition windows, heap headroom and payload size. Compare every retained outcome, including warnings and collector failures. These paced-response experiments extend the research; they do not establish a saturated-service threshold.</p><p class="mf-note"><strong>Evidence roles stay separate.</strong> Logging and priming choose later settings and are development. Update-set repetitions reuse seeds; headroom confirmation uses a fresh seed. Models use observed GC and fixed historical costs. A parameter that changes the winner in one pair is not a universal cache-selection rule.</p><label>Evidence cohort<select id="mf-cohort"></select></label><label>Latency channel<select id="mf-channel"></select></label><label>Percentile<select id="mf-q"><option>99</option><option selected>99.9</option><option>99.99</option><option>99.999</option></select></label><p id="mf-scope" aria-live="polite"></p><div id="mf-ratio" class="mf-scroll"></div><div id="mf-table" class="mf-scroll"></div><h3>Inspect one matched pair</h3><label>Retained comparison<select id="mf-pair"></select></label><div id="mf-detail" class="mf-scroll"></div><h3>Frozen conditional response models</h3><div id="mf-models" class="mf-scroll"></div><p>M0: pause-only residual; M1: residual plus old baseline; M2: FIFO queue drain from GC; M3core and M3total: M2 using unioned GC/safepoint envelopes. Constant: old pilot quantile. All are fixed before these runs. The 256 B arm has no numerical predictions because old costs were calibrated at 4 KiB.</p><button id="mf-load" type="button">Load full tail curves and stall rates</button><div id="mf-tail" class="mf-scroll"></div><div id="mf-rates" class="mf-scroll"></div><details><summary>Definitions and interpretation</summary><dl><dt>Update hot set</dt><dd>Number of resident keys eligible for fresh writes. Reads still range over all 32,768 keys. At 5% writes and 50,000 requests/s, 2,048 eligible keys have a nominal 0.82 s overwrite interval; 32,768 have 13.11 s. Locality and policy activity change too, so this is not a pure lifetime intervention.</dd><dt>Heap headroom</dt><dd>Extra JVM heap capacity available for allocation and collection. The 512/1,024 MiB limits are matched between backends. Equal heap limits do not mean equal total memory; native mapped storage and RSS also matter.</dd><dt>Phase priming</dt><dd>Four short invocations followed by a reduced warmup, holding total premeasurement time and logical operations fixed. It changes invocation boundaries and allocations as well as possible JIT behavior.</dd><dt>Scheduled response</dt><dd>Completion minus intended arrival. Requests that arrive during a pause accrue waiting and queue debt. Service measures the actual call; saturated closed-loop service weighs completed operations differently.</dd><dt>GC exposure</dt><dd>Fraction of the measurement window overlapping logged GC pauses. This describes time unavailable, not how many independent experiments support a rare quantile.</dd><dt>Safepoint envelope</dt><dd>Logged time around a JVM coordination stop, including reaching/cleanup/at/leaving components. M3core removes reach time; M3total keeps it. These are approximate availability proxies, not exact per-thread stop intervals.</dd><dt>Evacuation failure</dt><dd>G1 could not copy some objects into destination space. It is an intrinsic pressure outcome retained in the data, not a reason to discard a slow fork.</dd><dt>p99.999 support</dt><dd>About 15 nominal observations above the quantile in a 1.5-million-response window, or 45 in the 90-second transition window. Several can share the same stall. This is not an independent-sample count.</dd></dl></details><p><a class="mf-link" href="https://github.com/Enixes/TailCache/blob/codex/tailcache-preprint/docs/mechanism/RESULTS.md">All-point results and limitations</a> <a class="mf-link" href="mechanism-data.json" download="tailcache-mechanism-20261118.json">Download portable data</a></p></section>'''
 if not hosted:body=body.replace('href="mechanism-data.json"','href="mechanism/mechanism-data-20261118.json"')
 fs={r['id']:r for r in d['forks']};hot=[p for p in d['pairs'] if p['cohort'].startswith('hotset-')]
 if hot:
  narrow=[p for p in hot if fs[p['c']]['hotset']==2048];wide=[p for p in hot if fs[p['c']]['hotset']==32768]
  message=f"<p class='mf-note'><strong>Observed locality reversal at5% writes.</strong> With2048 eligible update keys, Caffeine has lower responsep99.9 in{sum(p['ratios']['response']['99.9']>1 for p in narrow)}/{len(narrow)} pairs; with32768 keys, Chronicle is lower in{sum(p['ratios']['response']['99.9']<1 for p in wide)}/{len(wide)} pairs. Screen and reversed-order repeat remain separate, with two seeds. This bundles value lifetime, locality and cache-policy activity.</p>"
  body=body.replace('<label>Evidence cohort',message+'<label>Evidence cohort')
 figures=json.loads((BASE/'figure-index-20261118.json').read_text());manifest=json.loads((BASE/'render-manifest-20261118.json').read_text());assert manifest['inputSha256']==hashlib.sha256(path.read_bytes()).hexdigest()
 gallery='<details><summary>Three scientific figures and captions</summary>'
 for i,r in enumerate(figures,1):
  file=BASE/'figures'/(r['id']+'.png');assert hashlib.sha256(file.read_bytes()).hexdigest()==manifest['outputs']['figures/'+file.name]
  src='mechanism-figures/'+file.name if hosted else 'data:image/png;base64,'+base64.b64encode(file.read_bytes()).decode()
  import html
  gallery+=f'<figure><img loading="lazy" src="{src}" alt="{html.escape(r["title"])}"><figcaption><strong>Figure C{i}.</strong> {html.escape(r["caption"])}</figcaption></figure>'
 gallery+='</details>';body=body.replace('</section>',gallery+'</section>')
 body=re.sub(r'\b(at|all|and|over|from|of|with|by|both|in|than|about|versus|only|uses|use|plus|the|contains|across|through|on|fixed|matched|before|after|separate|exact|strict|no|recorded|longer|shorter|intended|near|every|its|per|to)(?=\d)',r'\1 ',body)
 body=re.sub(r'(\d)(?=(?:MiB|KiB|GiB|B|ms|µs|seconds|second)\b)',r'\1 ',body);body=re.sub(r'\b(response|service|gap)(?=p\d)',r'\1 ',body)
 scripts='<script id="mf-data" type="application/json">'+raw+'</script>'
 if not hosted:scripts+='<script id="mf-full" type="application/json">'+full+'</script>'
 return START+css+body+scripts+'<script>'+(ROOT/'scripts/tailcache12_mechanism_ui.js').read_text()+'</script>'+END

def attach(page,hosted=False):
 old=strip(page);marker='<main class="wrap">';component=render(hosted);new=old.replace(marker,marker+component,1) if marker in old else re.sub(r'(<body[^>]*>)',lambda m:m[0]+component,old,count=1);assert strip(new)==old;return new

def main():
 p=argparse.ArgumentParser();p.add_argument('--site-out',type=pathlib.Path);a=p.parse_args()
 for name in ('TAILCACHE_RESULTS_EXPLORER.html','TAILCACHE_MIDPOINT_EXPLORER.html'):
  path=ROOT/'docs'/name;path.write_text(attach(path.read_text()))
 if a.site_out:
  path=a.site_out/'index.html';path.write_text(attach(path.read_text(),True));shutil.copyfile(BASE/'mechanism-data-20261118.json',a.site_out/'mechanism-data.json');shutil.copytree(BASE/'figures',a.site_out/'mechanism-figures',dirs_exist_ok=True)
 print('MECHANISM_EXPLORER_REBUILT_HISTORICAL_COMPONENTS_PRESERVED')
if __name__=='__main__':main()
